 old=BASE/'assembly/article_module_catalog_v7.json';cat=json.loads(old.read_text());assert all(sha(ROOT/n)==h for n,h in cat['sha256'].items());paths={old,Path(__file__)};reports={}
 specs=[('control_state_flip_flop','gf180_control_dff_v1','screen_gf180_control_dff_nominal.py','gf180_control_dff_nominal_src'),('native_event_phase_sequencer','gf180_event_phase_sequencer_v1','screen_gf180_event_phase_sequencer_native_drivers.py','gf180_event_phase_sequencer_native_drivers_src')]
